#include <iostream>
#include <algorithm>
#include <vector>
#include <map>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> arr(n);
    for (int I = 0; I < n; ++i) {
        cin >> arr[i];
    }
    map<int, int> freq;
    for (int I = 0; I < n; ++i) {
        freq[arr[i]]++;
    }
    int max_freq = 0;
    int max_freq_element = -1;
    for (auto it = freq.begin(); it!= freq.end(); ++it) {
        if (it->second > max_freq) {
            max_freq = it->second;
            max_freq_element = it->first;
        }
    }
    cout << "The most occurring element is " << max_freq_element << " with frequency " << max_freq << endl;
    int second_max_freq = 0;
    int second_max_freq_element = -1;
    for (auto it = freq.begin(); it!= freq.end(); ++it) {
        if (it->second > second_max_freq && it->first!= max_freq_element) {
            second_max_freq = it->second;
            second_max_freq_element = it->first;
        }
    }
    cout << "The second most occurring element is " << second_max_freq_element << " with frequency " << second_max_freq << endl;
    return 0;
}
```

